                                  int64_t stride,
                                  int64_t padding,
                                  int64_t dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled implicit-GEMM style Conv2d forward implemented with CuTe tensors.
//   M = N_batch * OH * OW   (output spatial positions, flattened)
//   N = C_out               (output channels)
//   K = C_in * KH * KW      (reduction dim, gathered from input on the fly)
// C[M,N] tile per CTA: BM x BN, k-chunks of BK staged in shared memory.

