// Asynchronous global->shared copy of one FP32 value (Ampere+ cp.async).
// A zero src_size zero-fills the destination, giving free padding/OOB
// handling without a register round-trip through the global data.
__device__ __forceinline__ void cp_async4(float* smem_dst,
                                          const float* gmem_src,
                                          bool valid) {
  unsigned saddr = (unsigned)__cvta_generic_to_shared(smem_dst);
  int src_size = valid ? 4 : 0;
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n"
               :: "r"(saddr), "l"(gmem_src), "r"(src_size));
