      c       = k / (KH * KW);
      int rem = k - c * KH * KW;
      kh      = rem / KW;
      kw      = rem - kh * KW;
    }
    sKC[0][kk] = c;
    sKH[0][kk] = kh;
    sKW[0][kk] = kw;
  }
  __syncthreads();
  // Stage A chunk 0 (async gather from input with zero-fill padding)
  #pragma unroll
  for (int it = 0; it < (BM * BK) / THREADS; ++it) {
    int idx = tid + it * THREADS;
    int kk  = idx % BK;
    int row = idx / BK;
    int m   = m_block + row;
    const float* src = Xp;
    bool valid = false;
    if (m < M_total && kk < K_total) {
      int ih = sRowIH[row] + sKH[0][kk] * dilation;
      int iw = sRowIW[row] + sKW[0][kk] * dilation;
      if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
        src = Xp + ((int64_t)sRowN[row] * C_in + sKC[0][kk]) * H * Win +
              (int64_t)ih * Win + iw;
        valid = true;
      }
    }
    cp_async4(smemA + kk * SASTEP + row, src, valid);
  }
  // Stage B chunk 0 (async filter-weight loads with zero-fill OOB)
  for (int idx = tid; idx < BK * BN; idx += THREADS) {
    int n  = idx % BN;
    int kk = idx / BN;
    int cg = n_block + n;
    const float* src = Wp;
    bool valid = (cg < C_out && kk < K_total);
    if (valid) {
      src = Wp + (int64_t)kk * C_out + cg;
    }
    cp_async4(smemB + kk * SBSTEP + n, src, valid);
  }
  cp_async_commit();
  cp_async_wait_all();
  __syncthreads();
  for (int chunk = 0; chunk < num_chunks; ++chunk) {
    const int cur = chunk & 1;
    const int nxt = cur ^ 1;
    const int k0  = chunk * BK;
    const int k0n = k0 + BK;
