    // the async global->shared copies bypass the register file and their
    // latency overlaps with the tensor-core MMA on the current buffers.
    if (k0n < K_total) {
      for (int kk = tid; kk < BK; kk += THREADS) {
        int k = k0n + kk;
        int c = 0, kh = 0, kw = 0;
        if (k < K_total) {
          c       = k / (KH * KW);
          int rem = k - c * KH * KW;
          kh      = rem / KW;
          kw      = rem - kh * KW;
        }
        sKC[nxt][kk] = c;
        sKH[nxt][kk] = kh;
        sKW[nxt][kk] = kw;
      }
      __syncthreads();
      #pragma unroll
      for (int it = 0; it < (BM * BK) / THREADS; ++it) {
        int idx = tid + it * THREADS;
        int kk  = idx % BK;
        int row = idx / BK;
        int m   = m_block + row;
        const float* src = Xp;
        bool valid = false;
        if (m < M_total && (k0n + kk) < K_total) {
          int ih = sRowIH[row] + sKH[nxt][kk] * dilation;
          int iw = sRowIW[row] + sKW[nxt][kk] * dilation;
          if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
            src = Xp + ((int64_t)sRowN[row] * C_in + sKC[nxt][kk]) * H * Win +
                  (int64_t)ih * Win + iw;
            valid = true;
          }
        }
        cp_async4(smemA + nxt * (BK * SASTEP) + kk * SASTEP + row, src, valid);
      }
      for (int idx = tid; idx < BK * BN; idx += THREADS) {
        int n  = idx % BN;
        int kk = idx / BN;
        int cg = n_block + n;
        const float* src = Wp;
        bool valid = (cg < C_out && (k0n + kk) < K_total);
        if (valid) {
          src = Wp + (int64_t)(k0n + kk) * C_out + cg;
        }
        cp_async4(smemB + nxt * (BK * SBSTEP) + kk * SBSTEP + n, src, valid);
      }
      cp_async_commit();
    }
    // ---- Compute: tensor-core MMA over the current k-chunk ----
    #pragma unroll
    for (int ks = 0; ks < BK; ks += 8) {
      // B fragments (8 x 8) are shared by both m16 tiles in this warp;
      // the 2x4 warp grid halves duplicate B shared-memory traffic vs 4x2.
      unsigned b0v[3], b1v[3];
      #pragma unroll
      for (int j = 0; j < 3; ++j) {
        const int bcol = wn * 24 + j * 8 + groupID;
        b0v[j] = f32_to_tf32(sB(ks + tig,     bcol, cur));
        b1v[j] = f32_to_tf32(sB(ks + tig + 4, bcol, cur));
      }
      #pragma unroll
      for (int mi = 0; mi < 2; ++mi) {
        const int arow = wm * 32 + mi * 16 + groupID;
        unsigned a0 = f32_to_tf32(sA(ks + tig,     arow,     cur));
        unsigned a1 = f32_to_tf32(sA(ks + tig,     arow + 8, cur));
        unsigned a2 = f32_to_tf32(sA(ks + tig + 4, arow,     cur));
        unsigned a3 = f32_to_tf32(sA(ks + tig + 4, arow + 8, cur));
        #pragma unroll
        for (int j = 0; j < 3; ++j) {
          mma_tf32_16x8x8(acc[mi][j][0], acc[mi][j][1], acc[mi][j][2], acc[mi][j][3],
