  #pragma unroll
  for (int mi = 0; mi < 2; ++mi) {
    #pragma unroll
    for (int j = 0; j < 3; ++j) {
      const int col0 = n_block + wn * 24 + j * 8 + tig * 2;
      #pragma unroll
      for (int r = 0; r < 4; ++r) {
