}

torch::Tensor cute_conv2d_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int64_t stride,
                                  int64_t padding,
                                  int64_t dilation)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C_in, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C_out, C_in, KH, KW]");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride/dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N_batch = x_c.size(0);
  const int64_t C_in    = x_c.size(1);
  const int64_t H       = x_c.size(2);
  const int64_t Win     = x_c.size(3);

  const int64_t C_out = w_c.size(0);
  const int64_t KH    = w_c.size(2);
  const int64_t KW    = w_c.size(3);
  const int64_t K_total = C_in * KH * KW;
  TORCH_CHECK(w_c.size(1) == C_in, "w.size(1) must equal C_in");

  const int64_t OH = (H   + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  const int64_t OW = (Win + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(OH > 0 && OW > 0, "Invalid output size");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C_out, "bias must be [C_out]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N_batch, C_out, OH, OW}, x_c.options());

  const int64_t M_total = N_batch * OH * OW;

  dim3 block(THREADS);
  dim3 grid((unsigned)((M_total + BM - 1) / BM),
            (unsigned)((C_out  + BN - 1) / BN));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  // Stage filters once per call in K-major order; this is tiny compared with
  // the conv and makes every CTA's B-tile prefetch fully coalesced.
  auto w_kn = torch::empty({K_total, C_out}, w_c.options());
  const int64_t wkn_numel = K_total * C_out;
  dim3 repack_block(256);
  dim3 repack_grid((unsigned)((wkn_numel + 255) / 256));
  repack_w_kn<<<repack_grid, repack_block, 0, stream>>>(
      w_c.data_ptr<float>(),
      w_kn.data_ptr<float>(),
      (int)C_out, (int)K_total);
  // Dynamic shared memory holds the double-buffered A/B staging tiles.
  const size_t smem_bytes =
      (size_t)(2 * BK * SASTEP + 2 * BK * SBSTEP) * sizeof(float);
  static bool smem_attr_set = false;
  if (!smem_attr_set) {
    cudaError_t serr = cudaFuncSetAttribute(
        conv2d_cute_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
    TORCH_CHECK(serr == cudaSuccess,
                "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(serr));
    smem_attr_set = true;
  }
  conv2d_cute_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_kn.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N_batch, (int)C_in, (int)H, (int)Win,
      (int)C_out, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)OH, (int)OW, (int)M_total);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
