//   M = N_batch * OH * OW   (output spatial positions, flattened)
//   N = C_out               (output channels)
//   K = C_in * KH * KW      (reduction dim, gathered from input on the fly)
// C[M,N] tile per CTA: BM x BN, k-chunks of BK staged in shared memory.

constexpr int BM       = 64;
constexpr int BN       = 96;
constexpr int BK       = 16;
constexpr int THREADS  = 256;
constexpr int SASTEP   = BM + 8; // padded leading dim for conflict-free MMA fragment loads
constexpr int SBSTEP   = BN + 8; // padded leading dim for conflict-free MMA fragment loads

// Convert FP32 to TF32 (round-to-nearest) for tensor-core MMA.
__device__ __forceinline__ unsigned f32_to_tf32(float f) {
  unsigned r;
  asm volatile("cvt.rna.tf32.f32 %0, %1;\n" : "=r"(r) : "f"(f));
  return r;
}
// Tensor-core MMA: D(16x8, FP32) += A(16x8, TF32) * B(8x8, TF32).
__device__ __forceinline__ void mma_tf32_16x8x8(float& d0, float& d1,
                                                float& d2, float& d3,
                                                unsigned a0, unsigned a1,
                                                unsigned a2, unsigned a3,
                                                unsigned b0, unsigned b1) {
